//! Rival civilisations on the player's home world (#212).
//!
//! The campaign's home planet (the eras' world, `src/world/terrain.js`, generated by #140's
//! Rust terrain) hosts several peoples besides the player's tribe, on its other continents.
//! They live in this crate's simulation, unchanged: ages, jobs, trade, alliances, wars and the
//! PPO war councils (#115) with the rules as fallback. The player's calm and stress tilt them
//! as in the sandbox. This module only joins that simulation to the campaign:
//!
//! - **One map.** [`home_terrain`] turns the home World's tile and height grid into civ terrain
//!   kinds, same size, wrapping both ways (#111). Land is land and sea is sea in both.
//! - **Rivals.** [`rival_count`] scales with the world (#220: Small 480×270 → 3, Medium
//!   640×360 → 5, Large 960×540 → 8, Huge 1280×720 → 12) and with the land there is.
//!   [`rival_sites`] spreads them over continents other than the player's, away from the spots
//!   where the player's colonies land. They arrive staggered, as the sandbox's rivals do
//!   (`World::prepare_rivals`).
//! - **The player as a mirrored faction.** The era scene stays authoritative for the player's
//!   own people. The simulation holds a faction that mirrors them: a village at the camp and at
//!   each colony, the era's age, and a few guards standing in for the tribe's fighters. Before
//!   every step it is pinned back to what the scene says ([`HomeWorld::pin`]), so the sim never
//!   grows, starves, splits or ages the player's people. What the rivals did to it (met it,
//!   traded with it, raided it, killed its guards, besieged it, declared war) is read back after
//!   the step and turned into [`HomeLine`]s, the player-facing events.
//! - **Across the sea.** Most rivals live on another landmass, where the sim's marches cannot
//!   reach the player. Rafts and colonies make contact ([`HomeWorld::contacts`]); after that,
//!   tension drifts with the same rule as in `politics`, and trade and raids cross the water by
//!   boat ([`HomeWorld::overseas`]).
//! - **The eras.** Stone Age: contact, raids (food stolen, people hurt) and trade (food).
//!   Industry: rival trade and wars move the goat market ([`HomeLine::market`]). Space Age: a
//!   launch race. Every line carries ticker text and an advisor line.
//!
//! The war councils never decide for the mirrored faction: [`MirrorGuard`] wraps whatever
//! `Policy` is plugged in and lets the mirror only make peace or man its walls. The council's
//! observation layout is untouched (`council::OBS_VERSION` stays).
//!
//! Everything is deterministic for a seed and a sequence of player states and steps.

use std::collections::VecDeque;
use std::fmt::Write;

use moc_planet::rng::Rng;

use crate::ages;
use crate::planet::Dims;
use crate::politics::{self, Decision, Policy};
use crate::terrain::{self, Region, Terrain};
use crate::world::*;

/// The home World's tile codes (`src/world/terrain.js` `T`).
pub mod tile {
    pub const DEEP: u8 = 0;
    pub const SHALLOW: u8 = 1;
    pub const SAND: u8 = 2;
    pub const GRASS: u8 = 3;
    pub const FOREST: u8 = 4;
    pub const HILL: u8 = 5;
    pub const MOUNTAIN: u8 = 6;
    pub const SNOW: u8 = 7;
    pub const FARM: u8 = 8;
    pub const ROAD: u8 = 9;
    pub const PAVED: u8 = 10;

    /// The JS `World.walkable`.
    pub fn walkable(t: u8) -> bool {
        t >= SAND && t != MOUNTAIN && t != SNOW
    }
}

/// Grass and forest at least this high (heights 0..1, sea level 0.33) are uplands to the
/// civilisations: hills (slower, poorer, easier to hold), still walkable land.
pub const UPLAND: f32 = 0.78;

/// The civ terrain kind of one home World tile.
pub fn civ_kind(t: u8, h: f32) -> u8 {
    match t {
        tile::DEEP => terrain::DEEP,
        tile::SHALLOW => terrain::WATER,
        tile::SAND => terrain::SAND,
        tile::GRASS | tile::FARM | tile::ROAD | tile::PAVED => {
            if h >= UPLAND {
                terrain::HILLS
            } else {
                terrain::GRASS
            }
        }
        tile::FOREST => {
            if h >= UPLAND {
                terrain::HILLS
            } else {
                terrain::FOREST
            }
        }
        tile::HILL => terrain::HILLS,
        tile::MOUNTAIN => terrain::MOUNTAIN,
        tile::SNOW => terrain::ICE,
        _ => terrain::DEEP,
    }
}

/// A campaign continent as the JS `World.continents` gives it (home first).
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct Continent {
    pub cx: f32,
    pub cy: f32,
    pub rx: f32,
    pub ry: f32,
    /// Where the player's settlement on it stands (the camp at home, the colonies elsewhere).
    pub village: (i32, i32),
}

/// The civ terrain of a home World: same size, same land and sea, wrapping both ways. Its
/// regions are the campaign's continents, home first.
pub fn home_terrain(w: usize, h: usize, types: &[u8], heights: &[f32], conts: &[Continent]) -> Terrain {
    let d = Dims { w, h };
    let n = d.n();
    let kind: Vec<u8> = (0..n).map(|i| civ_kind(types.get(i).copied().unwrap_or(0), heights.get(i).copied().unwrap_or(0.0))).collect();
    let regions = conts.iter().map(|c| Region { cx: c.cx, cy: c.cy, rx: c.rx.max(4.0), ry: c.ry.max(4.0), start: c.village }).collect();
    Terrain::from_kinds(d, kind, regions)
}

/// Rival peoples for a world of `w`×`h` tiles (#220's sizes, interpolated by area), before
/// the land check.
pub fn rival_count(w: usize, h: usize) -> usize {
    const P: [(f32, f32); 4] = [(480.0 * 270.0, 3.0), (640.0 * 360.0, 5.0), (960.0 * 540.0, 8.0), (1280.0 * 720.0, 12.0)];
    let a = (w * h) as f32;
    let n = if a <= P[0].0 {
        P[0].1
    } else if a >= P[3].0 {
        P[3].1
    } else {
        let k = (0..3).find(|&k| a <= P[k + 1].0).unwrap_or(2);
        let t = (a - P[k].0) / (P[k + 1].0 - P[k].0);
        P[k].1 + t * (P[k + 1].1 - P[k].1)
    };
    (n.round() as usize).clamp(RIVALS_MIN, RIVALS_MAX)
}

pub const RIVALS_MIN: usize = 3;
pub const RIVALS_MAX: usize = 12;
/// Land a rival people needs to itself (tiles), so a small world isn't crammed.
pub const LAND_PER_RIVAL: usize = 900;
/// Rival homelands are at least this far apart (tiles; a big continent may hold several).
pub const RIVAL_GAP: f32 = 46.0;
/// …and this far from where the player's camp or a colony of the player's stands.
pub const COLONY_GAP: f32 = 30.0;

/// Where the rivals begin: good land on continents other than the player's (never the player's
/// own landmass while another has room), spread by farthest-point picks, away from the
/// player's camp and colony spots. At most `n`; fewer if the land runs out.
pub fn rival_sites(t: &Terrain, conts: &[Continent], n: usize, seed: u32) -> Vec<(i32, i32)> {
    let d = t.d;
    let home = conts.first().map(|c| t.land(c.village.0, c.village.1)).unwrap_or(0);
    let spots: Vec<(i32, i32)> = conts.iter().map(|c| c.village).collect();
    let gap = |a: (i32, i32), b: (i32, i32)| d.dist(a.0 as f32, a.1 as f32, b.0 as f32, b.1 as f32);
    let mut area = std::collections::BTreeMap::<u16, usize>::new();
    for &l in &t.land_id {
        if l != 0 {
            *area.entry(l).or_insert(0) += 1;
        }
    }
    let roomy = |l: u16| l != 0 && l != home && area.get(&l).map_or(false, |&a| a >= 500);
    let mut rng = Rng::new(seed ^ 0x2120_51e5);
    let mut cands: Vec<(i32, i32)> = Vec::new();
    for _ in 0..40_000 {
        if cands.len() >= 5000 {
            break;
        }
        let i = rng.below(d.n());
        if !matches!(t.kind[i], terrain::GRASS | terrain::FOREST) || !roomy(t.land_id[i]) {
            continue;
        }
        // Room round it to grow.
        let (x, y) = ((i % d.w) as i32, (i / d.w) as i32);
        let room = (-3..=3).flat_map(|oy| (-3..=3).map(move |ox| (ox, oy))).filter(|&(ox, oy)| t.walkable(x + ox, y + oy)).count();
        if room < 40 {
            continue;
        }
        cands.push((x, y));
    }
    let mut sites: Vec<(i32, i32)> = Vec::new();
    while sites.len() < n {
        let best = cands
            .iter()
            .filter(|&&c| spots.iter().all(|&s| gap(s, c) >= COLONY_GAP))
            .map(|&c| {
                let near = sites.iter().map(|&s| gap(s, c)).fold(f32::MAX, f32::min);
                // Far from the other rivals first; then away from the player's home.
                let home_d = spots.first().map_or(0.0, |&s| gap(s, c));
                (near.min(400.0) + home_d * 0.05, near, c)
            })
            .filter(|&(_, near, _)| near >= RIVAL_GAP)
            .max_by(|a, b| a.0.total_cmp(&b.0));
        match best {
            Some((_, _, c)) => sites.push(c),
            None => break,
        }
    }
    sites
}

// ---------------------------------------------------------------------------------------
// The player's stage.
//
// The campaign moves through stages, each covering a few of the twenty ages (#222). The rivals
// follow the stage's range: the mirror stands at its top age, rivals arriving in a stage are
// brought up near its bottom (`catch_up`), and nobody climbs more than `AHEAD` ages past its
// top. What the rivals do to the player reads differently by the player's age ([`Phase`]):
// food and people for tribes, the goat market for industrial nations, a launch race in space.

/// Today's scenes (`src/main.js` SCENES) and their default age ranges, until a stage table
/// says otherwise: Stone Age, Farming to Kingdoms, Industry, Information Age, Space Age.
pub const ERAS: usize = 5;
pub const SCENE_AGES: [(u8, u8); ERAS] = [(1, 3), (4, 9), (13, 15), (16, 18), (19, 20)];
/// Simulated seconds per real second: in play, and in the cutscenes that skip millennia.
pub const SPEED_PLAY: f32 = 2.0;
pub const SPEED_SKIP: f32 = 10.0;
/// Rivals climb no further than this many ages past the top of the player's stage.
pub const AHEAD: u8 = 2;
/// How the player's people read, by their age.
pub type Phase = u8;
pub const ERA_STONE: Phase = 0;
pub const ERA_KINGDOMS: Phase = 1;
pub const ERA_INDUSTRY: Phase = 2;
pub const ERA_INFO: Phase = 3;
pub const ERA_SPACE: Phase = 4;

/// The phase of an age: tribes to 8, kingdoms to 13, industry to 17, the Information Age, space.
pub fn phase_of(age: u8) -> Phase {
    match age {
        0..=8 => ERA_STONE,
        9..=13 => ERA_KINGDOMS,
        14..=17 => ERA_INDUSTRY,
        18 => ERA_INFO,
        _ => ERA_SPACE,
    }
}

/// Agents per rival people the sim may hold, by phase (the frame budget; the ages from
/// Kingdoms on ask for about 150 people to hold, `ages::entry_population`).
pub const PHASE_PEOPLE: [usize; ERAS] = [130, 190, 190, 190, 190];
/// The mirrored faction's names, by phase.
const MIRROR_NAME: [&str; ERAS] = ["Chicken Clan", "Chicken Kingdom", "Chicken Republic", "Chicken Republic", "Chicken Federation"];

/// Kinds of player-facing lines.
pub mod he {
    /// You meet rival `rival`.
    pub const CONTACT: u8 = 1;
    /// They bring you food (`food` > 0).
    pub const TRADE: u8 = 2;
    /// They raid you: `food` < 0 stolen, `hurt` of your people killed.
    pub const RAID: u8 = 3;
    /// They besiege and sack one of your settlements.
    pub const SACK: u8 = 4;
    pub const WAR: u8 = 5;
    pub const PEACE: u8 = 6;
    /// They swear friendship with you.
    pub const ALLY: u8 = 7;
    /// A rival people appears.
    pub const ARRIVE: u8 = 8;
    /// A rival settles on your home continent.
    pub const LANDING: u8 = 9;
    /// News among the rivals (no effect on you, but `market` in the Industry scene).
    pub const WORLD: u8 = 10;
    /// The launch race (Space Age): `n` is the rival's progress in percent.
    pub const LAUNCH: u8 = 11;
    /// Your guards fought theirs: `hurt` of your people killed.
    pub const CLASH: u8 = 12;
}

/// One thing that happened between the rivals and the player (or among the rivals), in words
/// and in effects. The era scene applies the effects it understands.
#[derive(Clone, Debug, Default)]
pub struct HomeLine {
    pub seq: u32,
    pub kind: u8,
    /// `news::TONE_*`.
    pub tone: u8,
    /// The rival people (faction id), or -1.
    pub rival: i32,
    pub x: i32,
    pub y: i32,
    /// Food gained (+) or lost (−), in the Stone Age scene's units.
    pub food: f32,
    /// Your people killed.
    pub hurt: i32,
    /// Goat market shock, a fraction of the price (Industry).
    pub market: f32,
    /// A number the text uses (launch progress in percent).
    pub n: i32,
    /// Ticker headline.
    pub text: String,
    /// Advisor line (empty: none), its key, priority and cooldown.
    pub say: String,
    pub key: String,
    pub priority: u8,
    pub cooldown: u16,
}

pub const LINES_KEEP: usize = 128;

/// What the era scene says about the player's people this frame.
#[derive(Clone, Debug, Default)]
pub struct Player {
    /// Camp first, then colonies (tiles).
    pub sites: Vec<(i32, i32)>,
    /// Boats at sea (tiles).
    pub boats: Vec<(f32, f32)>,
    /// People.
    pub pop: u32,
    /// The larder, in the scene's units (Stone Age food).
    pub food: f32,
    /// Launch progress 0..1 (Space Age), and whether the rocket has flown.
    pub launch: f32,
    pub launched: bool,
}

/// One village of the mirrored faction.
#[derive(Clone, Copy, Debug)]
struct MVil {
    /// The sim's village (NO_V while sacked).
    v: u16,
    x: i32,
    y: i32,
    /// The food it was pinned to before the step.
    food: f32,
    /// Sacked: empty in the sim until this time.
    down: f32,
    /// The next fallen guard is replaced at this time (0: a new settlement).
    guard_t: f32,
}

/// A sacked settlement of the player's stays empty in the sim this long (simulated seconds).
pub const SACK_DOWN: f32 = 60.0;
/// A fallen guard is replaced after this long.
pub const GUARD_EVERY: f32 = 8.0;

/// A rival boat crossing the sea: a raid or a trade run.
#[derive(Clone, Copy, Debug)]
pub struct Boat {
    pub rival: u8,
    pub raid: bool,
    pub from: (f32, f32),
    pub to: (f32, f32),
    pub t: f32,
    pub eta: f32,
    /// The mirror village it sails for.
    target: usize,
}

impl Boat {
    pub fn pos(&self, d: Dims) -> (f32, f32) {
        let k = (self.t / self.eta.max(0.1)).clamp(0.0, 1.0);
        (d.wrap_xf(self.from.0 + d.dx(self.from.0, self.to.0) * k), d.wrap_yf(self.from.1 + d.dy(self.from.1, self.to.1) * k))
    }
}

/// Per rival: the overseas relation and what is owed to the player's ledger.
#[derive(Clone, Copy, Debug, Default)]
struct Ledger {
    /// The player's boats or colonies found the way to them (or they found the player's).
    route: bool,
    trade_cd: f32,
    raid_cd: f32,
    /// Food they gave (+) or took (−) not yet told, and when it was last told.
    food: f32,
    told_t: f32,
    /// Your guards they killed, not yet told.
    hurt: i32,
    /// Kills counted so far.
    kills: u32,
    /// Space Age: launch progress 0..1 and the last milestone told (quarters).
    launch: f32,
    told_q: u8,
    /// A seeded lag behind the player's age when a scene begins (negative: ahead).
    lag: i8,
    /// Was alive (arrival told).
    seen: bool,
    /// Had a village on the player's home continent.
    landed: bool,
}

/// Simulated seconds a Space Age rival needs to build its rocket (before bonuses).
pub const LAUNCH_SECONDS: f32 = 240.0;
/// Sailing speed of rival boats, tiles per simulated second.
pub const SAIL: f32 = 7.0;

/// How hard the rivals push the player (the game's Easy / Normal / Hard; the levels live in
/// the JS table, these are their numbers). Normal is all neutral.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Difficulty {
    /// Tilt on every rival's temper toward the player, added to its tension pressure per
    /// second like the player's stress (Easy −0.15, Hard +0.25). Never touches the council's
    /// observation layout: the councils see the tension it makes.
    pub aggression: f32,
    /// How often rivals raid the player (×).
    pub raids: f32,
    /// How much a raid takes and how many it hurts (×).
    pub damage: f32,
    /// How fast rival villages raise new people (×).
    pub growth: f32,
}

impl Default for Difficulty {
    fn default() -> Difficulty {
        Difficulty { aggression: 0.0, raids: 1.0, damage: 1.0, growth: 1.0 }
    }
}

impl Difficulty {
    pub fn clamped(self) -> Difficulty {
        let f = |v: f32, lo: f32, hi: f32, d: f32| if v.is_finite() { v.clamp(lo, hi) } else { d };
        Difficulty { aggression: f(self.aggression, -1.0, 1.0, 0.0), raids: f(self.raids, 0.0, 4.0, 1.0), damage: f(self.damage, 0.0, 4.0, 1.0), growth: f(self.growth, 0.25, 3.0, 1.0) }
    }
}

/// The rival world: the simulation, the mirrored faction and the ledger between them.
pub struct HomeWorld {
    pub w: World,
    pub conts: Vec<Continent>,
    /// The mirrored faction (the player's people).
    pub mirror: u8,
    /// The player's stage: its lowest and highest age, and whether it is a cutscene.
    pub age_lo: u8,
    pub age_hi: u8,
    pub fast: bool,
    pub player: Player,
    pub lines: VecDeque<HomeLine>,
    pub next_seq: u32,
    /// Lines told so far, by kind (`he::*`).
    pub tally: [u32; 16],
    pub boats: Vec<Boat>,
    pub difficulty: Difficulty,
    /// A rival has reached orbit.
    pub orbit: bool,
    rng: Rng,
    vils: Vec<MVil>,
    proxies: Vec<u32>,
    losses: u32,
    ledger: Vec<Ledger>,
    news_seen: u32,
    // Buffers JS reads.
    pub agents_buf: Vec<f32>,
    pub villages_buf: Vec<f32>,
    pub boats_buf: Vec<f32>,
    pub rivals_buf: Vec<f32>,
    pub territory: Vec<u8>,
    pub text: String,
}

/// Floats per agent (x, y, faction, id, kind), village, boat and rival in the JS buffers.
pub const AGENT_STRIDE: usize = 5;
pub const VILLAGE_STRIDE: usize = 9;
pub const BOAT_STRIDE: usize = 5;
pub const RIVAL_STRIDE: usize = 16;

/// Mirror villages are pinned to at most this much food, so the sim never spends it on
/// people (`SPAWN_COST` + 0.5) and other peoples' grain still reaches it (`politics::trade`
/// feeds villages under 4).
const MIRROR_FOOD_MAX: f32 = 3.4;
const COLONY_FOOD: f32 = 1.0;

impl HomeWorld {
    /// A home world's rivals: the map from the home World, `rivals` peoples (0: by size, plus
    /// the difficulty's `offset`) waiting on the other continents, and the player's mirrored
    /// faction at the camp.
    pub fn new(seed: u32, w: usize, h: usize, types: &[u8], heights: &[f32], conts: &[Continent], rivals: usize, offset: i32) -> HomeWorld {
        let t = home_terrain(w, h, types, heights, conts);
        let mut world = World::with_terrain(seed, t);
        // Rival peoples, not a crowded planet: fewer agents than the sandbox, for the frame budget.
        let land = world.land_tiles as usize;
        let other_land = {
            let home = conts.first().map(|c| world.terrain.land(c.village.0, c.village.1)).unwrap_or(0);
            world.terrain.land_id.iter().filter(|&&l| l != 0 && l != home).count()
        };
        let want = if rivals == 0 { (rival_count(w, h) as i32 + offset).clamp(1, (RIVALS_MAX + 2) as i32) as usize } else { rivals.clamp(1, RIVALS_MAX + 2) };
        let fit = (other_land / LAND_PER_RIVAL).max(RIVALS_MIN.min(want));
        let n = want.min(fit);
        let _ = land;
        // The player's people: first slot, the mirror.
        let mseed = seed ^ 0x00c4_1c4e;
        let traits = Traits { friendliness: 0.55, aggressiveness: 0.25, violence: 0.3, fertility: 0.5, cohesion: 0.85 };
        let mirror = world.add_faction(mseed, SeedSource::Mind, traits, NO_F, Some((MIRROR_NAME[0].to_string(), "Chicken".to_string())));
        {
            let f = &mut world.factions[mirror as usize];
            f.is_player = true;
            f.color = [255, 224, 102];
            f.region = 0;
            f.start = conts.first().map(|c| c.village).unwrap_or((0, 0));
        }
        let sites = rival_sites(&world.terrain, conts, n, seed);
        world.prepare_rivals(&sites);
        const COLOURS: [[u8; 3]; 12] = [
            [232, 70, 62],
            [66, 136, 246],
            [186, 92, 226],
            [56, 212, 222],
            [250, 140, 40],
            [244, 108, 172],
            [120, 230, 120],
            [238, 238, 238],
            [150, 96, 52],
            [0, 150, 130],
            [200, 30, 110],
            [100, 70, 160],
        ];
        let mut rng = Rng::new(seed ^ 0x2120_0bad);
        let mut ledger = vec![Ledger::default(); MAX_FACTIONS];
        for (k, &(f, _)) in world.setup.rivals.iter().enumerate() {
            world.factions[f as usize].color = COLOURS[k % COLOURS.len()];
            world.factions[f as usize].region = conts.iter().position(|c| world.terrain.land(c.village.0, c.village.1) == world.terrain.land(sites[k].0, sites[k].1)).unwrap_or(255) as u8;
            ledger[f as usize].lag = rng.below(4) as i8 - 1;
        }
        world.refresh_info();
        let mut hw = HomeWorld {
            w: world,
            conts: conts.to_vec(),
            mirror,
            age_lo: SCENE_AGES[0].0,
            age_hi: SCENE_AGES[0].1,
            fast: false,
            player: Player { sites: conts.first().map(|c| vec![c.village]).unwrap_or_default(), pop: 10, food: 0.0, ..Default::default() },
            lines: VecDeque::new(),
            next_seq: 0,
            tally: [0; 16],
            boats: Vec::new(),
            difficulty: Difficulty::default(),
            orbit: false,
            rng: Rng::new(seed ^ 0x0212_0212),
            vils: Vec::new(),
            proxies: Vec::new(),
            losses: 0,
            ledger,
            news_seen: 0,
            agents_buf: Vec::new(),
            villages_buf: Vec::new(),
            boats_buf: Vec::new(),
            rivals_buf: vec![0.0; MAX_FACTIONS * RIVAL_STRIDE],
            territory: Vec::new(),
            text: String::new(),
        };
        hw.set_caps();
        hw.pin();
        hw.w.recount();
        hw.w.refresh_info();
        hw.snapshot();
        hw
    }

    /// Rival peoples (waiting or living).
    pub fn rivals(&self) -> impl Iterator<Item = u8> + '_ {
        self.w.setup.rivals.iter().map(|r| r.0)
    }

    pub fn rival_total(&self) -> usize {
        self.w.setup.rivals.len()
    }

    /// Rival peoples alive now (rebels split from them count too).
    pub fn rivals_alive(&self) -> usize {
        self.w.factions.iter().filter(|f| f.alive && f.id != self.mirror).count()
    }

    /// The player's stage: ages `lo..=hi`, `fast` for a cutscene. The mirror takes the top age
    /// and its phase's name; call [`HomeWorld::catch_up`] after a jump.
    pub fn set_stage(&mut self, lo: u8, hi: u8, fast: bool) {
        let n = crate::ages_table::AGE_COUNT as u8;
        let (lo, hi) = (lo.clamp(1, n), hi.clamp(1, n));
        let (lo, hi) = (lo.min(hi), hi.max(lo));
        self.fast = fast;
        if (lo, hi) == (self.age_lo, self.age_hi) {
            return;
        }
        self.age_lo = lo;
        self.age_hi = hi;
        self.w.factions[self.mirror as usize].name = MIRROR_NAME[self.phase() as usize].to_string();
        self.set_caps();
        self.pin();
    }

    /// Today's scenes by number (`SCENE_AGES`).
    pub fn set_era(&mut self, scene: u8) {
        let k = (scene as usize).min(ERAS - 1);
        let (lo, hi) = SCENE_AGES[k];
        self.set_stage(lo, hi, k == 1 || k == 3);
    }

    /// How the player's people read now.
    pub fn phase(&self) -> Phase {
        phase_of(self.age_hi)
    }

    /// The mirror's age: the top of the stage.
    pub fn player_age(&self) -> u8 {
        self.age_hi
    }

    /// Simulated seconds per real second now.
    pub fn speed(&self) -> f32 {
        if self.fast {
            SPEED_SKIP
        } else {
            SPEED_PLAY
        }
    }

    /// Bring every living rival up to its place in this stage: the bottom of the stage's range
    /// less its seeded lag (−1..=2). The cutscenes skip millennia, so peoples that fell behind are
    /// lifted to that age
    /// (with the people it asks for, so they don't fall straight into a Dark Age) and told in
    /// one line each. Peoples already there are left alone. Returns how many were lifted.
    pub fn catch_up(&mut self) -> usize {
        let target = self.age_lo;
        let mut lifted = 0;
        let peoples: Vec<u8> = self.rivals().collect();
        for f in peoples {
            // The peoples placed at the start; rebels split from them keep their own ways.
            if !self.w.factions[f as usize].alive {
                continue;
            }
            let lag = self.ledger[f as usize].lag;
            let want = (target as i32 - lag as i32).clamp(1, crate::ages_table::AGE_COUNT as i32) as u8;
            let age = self.w.factions[f as usize].age;
            if age >= want {
                continue;
            }
            self.lift(f, want);
            lifted += 1;
            let name = self.w.factions[f as usize].name.clone();
            let (x, y) = self.capital_xy(f);
            let age_name = ages::name(want);
            self.push(HomeLine {
                kind: he::WORLD,
                tone: crate::news::TONE_INFO,
                rival: f as i32,
                x,
                y,
                text: format!("Across the sea, the {name} have reached the {age_name}"),
                ..Default::default()
            });
        }
        lifted
    }

    /// Lift rival `f` to age `n`: the age, its buildings and jobs, and enough people and
    /// villages to hold it.
    fn lift(&mut self, f: u8, n: u8) {
        let w = &mut self.w;
        {
            let fac = &mut w.factions[f as usize];
            fac.age = n;
            fac.peak_age = fac.peak_age.max(n);
            fac.age_t = 0.0;
            fac.ready_t = 0.0;
            fac.low_pop_t = 0.0;
            fac.low_stab_t = 0.0;
            fac.dark_t = 0.0;
            fac.collapse_cd = fac.collapse_cd.max(60.0);
            fac.metrics.knowledge = fac.metrics.knowledge.max(0.1 * n as f32);
        }
        // People: the share of the age's entry population it must keep, plus a margin.
        let need = (crate::ages_table::COLLAPSE_POP_SHARE * ages::entry_population(n) * 1.15).ceil() as u32;
        w.recount();
        let mut have = w.factions[f as usize].pop;
        let villages: Vec<u16> = (0..w.villages.len() as u16).filter(|&v| w.villages[v as usize].alive && w.villages[v as usize].owner == f).collect();
        if villages.is_empty() {
            return;
        }
        // More villages round the capital so the people have homes (about 12 each).
        let mut homes = villages.clone();
        let want_v = (need as usize).div_ceil(12).min(politics::max_villages(n) as usize);
        let mut tries = 0;
        while homes.len() < want_v && tries < 200 && w.villages.iter().filter(|v| v.alive).count() < w.cap_villages {
            tries += 1;
            let from = homes[self.rng.below(homes.len())];
            let (ox, oy) = (w.villages[from as usize].x, w.villages[from as usize].y);
            if let Some((sx, sy)) = politics::pick_site(w, f, ox, oy, ox, oy) {
                let v = w.found_village(f, sx, sy, 6.0, false);
                homes.push(v);
            }
        }
        for &v in &homes {
            let vil = &mut w.villages[v as usize];
            vil.food = vil.food.max(8.0);
            vil.radius = vil.radius.max(START_RADIUS + 2);
            let r = vil.radius;
            w.claim_land(v, r);
        }
        let mut k = 0;
        while have < need && w.agents.len() < w.cap_agents {
            let v = homes[k % homes.len()];
            k += 1;
            let (x, y) = (w.villages[v as usize].x, w.villages[v as usize].y);
            let job = crate::jobs::choose(w, v);
            if let Some(a) = w.spawn_agent(f, v, job, x, y) {
                w.agents[a].age = self.rng.range(5.0, 40.0);
            }
            have += 1;
        }
        // Build what the age offers at once (the cutscene skipped the centuries of building).
        for &v in &homes {
            for b in crate::ages_table::Building::ALL {
                if b.unlock_age() <= n && self.rng.chance(0.7) {
                    w.villages[v as usize].built |= 1u64 << b as u8;
                }
            }
        }
        ages::refresh_fx(w, f);
        w.recount();
    }

    /// Agent and village limits for the scene: tribes in the Stone Age, nations later; kept
    /// low enough for the frame budget.
    fn set_caps(&mut self) {
        let n = self.rival_total().max(1);
        let per = PHASE_PEOPLE[self.phase() as usize];
        let land = self.w.land_tiles as usize;
        self.w.cap_agents = (per * n + 150).min((land / 10).max(400));
        self.w.cap_villages = (26 * n + 30).clamp(80, 420);
    }

    fn capital_xy(&self, f: u8) -> (i32, i32) {
        let fac = &self.w.factions[f as usize];
        self.w.villages.get(fac.capital as usize).filter(|v| v.alive && v.owner == f).map(|v| (v.x, v.y)).unwrap_or(fac.start)
    }

    /// Run `sim_dt` simulated seconds (in pinned chunks of at most 0.4 s), then read back what
    /// happened to the player.
    pub fn advance(&mut self, sim_dt: f32) {
        let mut left = sim_dt.max(0.0).min(60.0);
        self.w.speed = 1.0;
        while left > 1e-4 {
            let chunk = left.min(MAX_SUBSTEP * MAX_STEPS_PER_ADVANCE as f32);
            left -= chunk;
            self.pin();
            self.w.advance(chunk);
            self.tilt(chunk);
            self.harvest(chunk);
            self.contacts(chunk);
            self.overseas(chunk);
            self.launch_race(chunk);
        }
        self.snapshot();
    }

    /// The difficulty's hand on the rivals: their temper toward the player, how soon they raid
    /// again, and how fast their villages grow.
    fn tilt(&mut self, dt: f32) {
        let m = self.mirror;
        let k = self.difficulty;
        for r in 0..MAX_FACTIONS as u8 {
            if r == m || !self.w.factions[r as usize].alive {
                continue;
            }
            let rl = self.w.rel_mut(r, m);
            if rl.met && k.aggression != 0.0 {
                rl.tension = (rl.tension + politics::TENSION_RATE * k.aggression * dt).clamp(-1.0, 2.0);
            }
            if rl.cooldown > 0.0 && k.raids != 1.0 {
                rl.cooldown += dt * (1.0 - k.raids);
            }
        }
        // The scene's times: nobody runs off into the future while the player is in the past.
        let cap = self.age_hi.saturating_add(AHEAD);
        for f in self.w.factions.iter_mut().filter(|f| f.alive && f.id != m && f.age >= cap) {
            f.ready_t = 0.0;
        }
        if k.growth != 1.0 {
            for v in self.w.villages.iter_mut().filter(|v| v.alive && v.owner != m) {
                v.spawn_t = (v.spawn_t + dt * (k.growth - 1.0)).max(0.0);
            }
        }
    }

    // -----------------------------------------------------------------------------------
    // The mirror.

    /// Pin the mirrored faction to the scene: its villages at the player's camp and colonies,
    /// its age, its guards, its food; and none of the sim's own life for it (no growth,
    /// settlers, unrest, rebellion, strife, crises, plague, Dark Ages or vassalage).
    pub fn pin(&mut self) {
        let m = self.mirror;
        let era = self.phase() as usize;
        let age = self.player_age();
        let inputs = self.w.inputs;
        {
            let changed = self.w.factions[m as usize].age != age;
            let f = &mut self.w.factions[m as usize];
            f.alive = true;
            f.age = age;
            f.peak_age = age;
            f.age_t = 0.0;
            f.ready_t = 0.0;
            f.low_stab_t = 0.0;
            f.low_pop_t = 0.0;
            f.dark_t = 0.0;
            f.collapse_cd = 999.0;
            f.rebel_cd = 999.0;
            f.famine_cd = 999.0;
            f.strife_cd = 999.0;
            f.crisis_cd = 999.0;
            f.homeless_t = 0.0;
            f.succession = false;
            f.drought_t = 0.0;
            f.strike_t = 0.0;
            f.censor_t = 0.0;
            f.blackout_t = 0.0;
            f.tax_t = 0.0;
            f.starved_recent = 0.0;
            f.overlord = NO_F;
            // The player's mood is the people's temper: calm makes them open, stress prickly.
            let calm = inputs.calm.clamp(0.0, 1.0);
            let stress = inputs.stress.clamp(0.0, 1.0);
            let anger = inputs.anger.clamp(0.0, 1.0);
            f.traits.friendliness = (0.35 + 0.45 * calm - 0.2 * anger).clamp(0.05, 0.95);
            f.traits.aggressiveness = (0.15 + 0.4 * stress + 0.2 * anger).clamp(0.05, 0.95);
            if changed {
                ages::refresh_fx(&mut self.w, m);
            }
        }
        // No strife inside the player's people: the scene tells its own story.
        for k in 0..self.w.strifes.len() {
            if self.w.strifes[k].alive && self.w.strifes[k].civ == m {
                crate::conflict::end(&mut self.w, k, None);
            }
        }
        // Villages: one per site (camp first). A settlement sacked a moment ago stays empty in
        // the sim for a while (`SACK_DOWN`): its people hid, the attackers moved on.
        let now = self.w.time;
        let sites = self.player.sites.clone();
        let mut keep = vec![false; self.vils.len()];
        let mut vils: Vec<MVil> = Vec::new();
        for (si, &(sx, sy)) in sites.iter().enumerate() {
            let (sx, sy) = (self.w.d.wrap_x(sx), self.w.d.wrap_y(sy));
            let found = self.vils.iter().enumerate().find(|(k, mv)| !keep[*k] && self.w.d.cheb(mv.x, mv.y, sx, sy) <= 3).map(|(k, _)| k);
            let mut mv = match found {
                Some(k) => {
                    keep[k] = true;
                    self.vils[k]
                }
                None => MVil { v: NO_V, x: sx, y: sy, food: 0.0, down: 0.0, guard_t: 0.0 },
            };
            if mv.down > now {
                vils.push(mv);
                continue;
            }
            let ok = mv.v != NO_V && self.w.villages.get(mv.v as usize).map_or(false, |v| v.alive);
            if !ok {
                mv.v = self.found(sx, sy);
            } else if self.w.villages[mv.v as usize].owner != m {
                // Taken between two reads: the scene still holds it.
                self.w.villages[mv.v as usize].owner = m;
                self.w.transfer_land(mv.v, m);
            }
            let colony = si > 0;
            let food = if colony { COLONY_FOOD } else { self.player.food.clamp(0.0, MIRROR_FOOD_MAX) };
            let r = START_RADIUS + if era >= ERA_INDUSTRY as usize { 3 } else if era >= ERA_KINGDOMS as usize { 2 } else { 0 };
            let vil = &mut self.w.villages[mv.v as usize];
            vil.food = food;
            vil.unrest = 0.0;
            vil.hp = 1.0;
            vil.empty_t = 0.0;
            vil.settler_t = 999.0;
            vil.spawn_t = 0.0;
            vil.plague = 0.0;
            vil.mourn_t = 0.0;
            vil.camp = 0;
            vil.side = 0;
            if vil.radius != r {
                vil.radius = r;
                self.w.claim_land(mv.v, r);
            }
            mv.food = food;
            vils.push(mv);
        }
        // Settlements the scene no longer has are gone (quietly).
        let gone: Vec<u16> = self.vils.iter().enumerate().filter(|(k, mv)| !keep[*k] && mv.v != NO_V && !vils.iter().any(|o| o.v == mv.v)).map(|(_, mv)| mv.v).collect();
        for v in gone {
            self.drop_village(v);
        }
        self.vils = vils;
        if let Some(c) = self.vils.iter().find(|mv| mv.v != NO_V && mv.down <= now) {
            self.w.factions[m as usize].capital = c.v;
        }
        self.pin_guards();
    }

    /// A settlement of the mirror leaves the sim (quietly).
    fn drop_village(&mut self, v: u16) {
        let vil = &mut self.w.villages[v as usize];
        if vil.alive {
            vil.alive = false;
            vil.died = self.w.time;
            self.w.release_land(v);
        }
    }

    fn found(&mut self, x: i32, y: i32) -> u16 {
        let v = self.w.found_village(self.mirror, x, y, 0.0, false);
        self.w.villages[v as usize].built |= 1u64 << Building::Campfire as u8;
        v
    }

    /// Guards standing in for the player's fighters: a few per settlement, more with more
    /// people, kept at home, fed and of fighting age. Those the rivals kill are told as the
    /// player's dead (`harvest`); the scene's own people are never moved. A fallen guard is
    /// replaced only after `GUARD_EVERY` seconds, so a real attack can break through.
    fn pin_guards(&mut self) {
        let m = self.mirror;
        let now = self.w.time;
        let n_v = self.vils.len();
        let total = (self.player.pop / 2).clamp(2, 24) as usize;
        let camp_n = (total / 2).max(1);
        let col_n = if n_v > 1 { ((total - camp_n) / (n_v - 1)).clamp(1, 4) } else { 0 };
        let want = |k: usize| if k == 0 { camp_n } else { col_n };
        let mut have = vec![0usize; n_v];
        let mut keep: Vec<u32> = Vec::new();
        for i in 0..self.w.agents.len() {
            let a = &self.w.agents[i];
            if !a.alive || a.faction != m {
                continue;
            }
            if !self.proxies.contains(&a.id) || a.prisoner > 0.0 {
                // Not ours to keep (a captive, or one the sim made): stood down, quietly.
                if a.prisoner <= 0.0 {
                    self.w.agents[i].alive = false;
                }
                continue;
            }
            let k = self.vils.iter().position(|mv| mv.v == a.home && mv.down <= now);
            match k {
                Some(k) if have[k] < want(k) => {
                    have[k] += 1;
                    keep.push(a.id);
                    let a = &mut self.w.agents[i];
                    a.job = Job::Guard;
                    a.garrison = true;
                    a.food = 1.0;
                    a.age = 25.0;
                    a.life = a.life.max(80.0);
                    a.carry = 0.0;
                }
                _ => self.w.agents[i].alive = false,
            }
        }
        for k in 0..n_v {
            let mv = self.vils[k];
            if mv.v == NO_V || mv.down > now {
                continue;
            }
            // New settlements are manned at once; losses are made good one at a time.
            let fresh = mv.guard_t == 0.0;
            while have[k] < want(k) && (fresh || now >= self.vils[k].guard_t) {
                have[k] += 1;
                if let Some(a) = self.w.spawn_agent(m, mv.v, Job::Guard, mv.x, mv.y) {
                    let ag = &mut self.w.agents[a];
                    ag.garrison = true;
                    ag.age = 25.0;
                    ag.life = 100.0;
                    keep.push(ag.id);
                }
                if !fresh {
                    self.vils[k].guard_t = now + GUARD_EVERY;
                    break;
                }
            }
            if fresh {
                self.vils[k].guard_t = now.max(1e-3);
            }
        }
        self.proxies = keep;
        self.losses = self.w.factions[m as usize].losses;
    }

    // -----------------------------------------------------------------------------------
    // Reading back.

    /// After a step: what the rivals did to the mirror (food taken or given, guards killed,
    /// settlements taken, wars, peace, friendship), and the rivals' own news, as lines.
    fn harvest(&mut self, dt: f32) {
        let m = self.mirror;
        let now = self.w.time;
        for l in self.ledger.iter_mut() {
            l.trade_cd -= dt;
            l.raid_cd -= dt;
        }
        // Events, paired with the news lines they made (same order; kind and place match).
        let events = std::mem::take(&mut self.w.events);
        let news: Vec<crate::news::NewsLine> = self.w.news.lines.iter().filter(|l| l.seq >= self.news_seen).cloned().collect();
        self.news_seen = self.w.news.next;
        let mut ni = 0;
        let mut raider: Option<(u8, i32, i32)> = None;
        for e in &events {
            let line = match news.get(ni) {
                Some(l) if l.kind == e.kind && l.x == e.x && l.y == e.y => {
                    ni += 1;
                    Some(l.clone())
                }
                _ => None,
            };
            let (a, b) = (e.a, e.b);
            let mine = a == m as i32 || b == m as i32;
            let other = if a == m as i32 { b } else { a };
            if mine {
                if other < 0 || other == m as i32 {
                    continue;
                }
                let r = other as u8;
                match e.kind {
                    ev::CONTACT => self.tell_contact(r, e.x, e.y, false),
                    ev::WAR => self.tell(he::WAR, r, e.x, e.y),
                    ev::PEACE => self.tell(he::PEACE, r, e.x, e.y),
                    ev::RAID if b == m as i32 => raider = Some((r, e.x, e.y)),
                    ev::CAPTURE if b == m as i32 => {
                        // Sacked: the settlement empties for a while; the scene keeps it.
                        let k = self.vils.iter().position(|mv| mv.v != NO_V && mv.x == e.x && mv.y == e.y);
                        if let Some(k) = k {
                            let v = self.vils[k].v;
                            self.vils[k].down = now + SACK_DOWN;
                            self.vils[k].v = NO_V;
                            self.drop_village(v);
                        }
                        let hurt = e.n.clamp(0, 4);
                        self.ledger[r as usize].hurt += hurt;
                        self.tell_sack(r, e.x, e.y);
                    }
                    ev::VASSAL | ev::TRUCE => {
                        // A pact: friendship, not tribute (the scene keeps its own ruler).
                        for (p, q) in [(m, r), (r, m)] {
                            let rl = self.w.rel_mut(p, q);
                            rl.tension = rl.tension.min(-0.4);
                        }
                        self.tell(he::ALLY, r, e.x, e.y);
                    }
                    _ => {}
                }
                continue;
            }
            match e.kind {
                ev::CIV_FOUNDED if a >= 0 => {
                    let r = a as u8;
                    if !self.ledger[r as usize].seen {
                        self.ledger[r as usize].seen = true;
                        self.tell_arrival(r, e.x, e.y);
                    }
                }
                ev::COLONY | ev::FOUNDED if a >= 0 => {
                    // A rival settles on the player's home continent.
                    let home = self.conts.first().map(|c| self.w.terrain.land(c.village.0, c.village.1)).unwrap_or(0);
                    let r = a as u8;
                    if home != 0 && self.w.terrain.land(e.x, e.y) == home && !self.ledger[r as usize].landed {
                        self.ledger[r as usize].landed = true;
                        self.tell(he::LANDING, r, e.x, e.y);
                    }
                }
                _ => {
                    if let Some(l) = line {
                        self.tell_world(e, &l);
                    }
                }
            }
        }
        // Food: what the raiders took and the traders brought, village by village.
        let mut lost = 0.0;
        let mut gained = 0.0;
        for mv in &self.vils {
            if mv.v == NO_V || mv.down > now {
                continue;
            }
            let vil = &self.w.villages[mv.v as usize];
            if !vil.alive || vil.owner != m {
                continue;
            }
            let d = vil.food - mv.food;
            if d <= -0.25 {
                lost += -d;
            } else if d >= 1.0 {
                gained += d;
            }
        }
        if lost > 0.0 {
            let r = raider.map(|r| r.0).or_else(|| self.most_hostile());
            if let Some(r) = r {
                self.ledger[r as usize].food -= lost * self.difficulty.damage;
                let (x, y) = raider.map(|r| (r.1, r.2)).unwrap_or(self.vils.first().map(|v| (v.x, v.y)).unwrap_or((0, 0)));
                if raider.is_some() || now - self.ledger[r as usize].told_t > 12.0 {
                    self.tell_raid(r, x, y);
                }
            }
        }
        if gained > 0.0 {
            if let Some(r) = self.last_trader() {
                self.ledger[r as usize].food += gained;
                // One shipment at a time: the next waits (the sim would send one every 6 s).
                self.w.rel_mut(r, m).trade_t = self.rng.range(40.0, 60.0);
                if now - self.ledger[r as usize].told_t > 20.0 {
                    let (x, y) = self.vils.first().map(|v| (v.x, v.y)).unwrap_or((0, 0));
                    self.tell_trade(r, x, y);
                }
            }
        }
        // Guards killed in fights with the rivals.
        let losses = self.w.factions[m as usize].losses;
        if losses > self.losses {
            let raw = (losses - self.losses) as f32 * self.difficulty.damage;
            let dead = if raw > 0.0 && raw < 1.0 { self.rng.chance(raw) as i32 } else { raw.round() as i32 };
            self.losses = losses;
            // The killers: whoever's kill count rose most among those hostile to us.
            let mut best: Option<(u32, u8)> = None;
            for f in 0..MAX_FACTIONS as u8 {
                if f == m || !self.w.factions[f as usize].alive {
                    continue;
                }
                let k = self.w.factions[f as usize].kills;
                let delta = k.saturating_sub(self.ledger[f as usize].kills);
                if delta > 0 && best.map_or(true, |b| delta > b.0) {
                    best = Some((delta, f));
                }
            }
            if let Some(r) = best.map(|b| b.1).or_else(|| self.most_hostile()) {
                self.ledger[r as usize].hurt += dead;
                if raider.is_none() && lost <= 0.0 && now - self.ledger[r as usize].told_t > 15.0 {
                    let (x, y) = self.vils.first().map(|v| (v.x, v.y)).unwrap_or((0, 0));
                    self.tell_clash(r, x, y);
                }
            }
        }
        for f in 0..MAX_FACTIONS {
            self.ledger[f].kills = self.w.factions[f].kills;
        }
    }

    /// The rival most hostile to the player (at war or raiding first, then by tension).
    fn most_hostile(&self) -> Option<u8> {
        let m = self.mirror;
        (0..MAX_FACTIONS as u8)
            .filter(|&f| f != m && self.w.factions[f as usize].alive && self.w.rel(f, m).met)
            .max_by(|&a, &b| {
                let k = |f: u8| self.w.rel(f, m).war as f32 * 10.0 + self.w.rel(f, m).tension;
                k(a).total_cmp(&k(b)).then(b.cmp(&a))
            })
    }

    /// The rival that traded with the player most recently.
    fn last_trader(&self) -> Option<u8> {
        let m = self.mirror;
        (0..MAX_FACTIONS as u8)
            .filter(|&f| f != m && self.w.factions[f as usize].alive && self.w.rel(f, m).met)
            .min_by(|&a, &b| self.w.rel(a, m).traded_t.total_cmp(&self.w.rel(b, m).traded_t).then(a.cmp(&b)))
    }

    // -----------------------------------------------------------------------------------
    // Contact and the sea.

    fn meet(&mut self, r: u8, x: i32, y: i32, route: bool) {
        let m = self.mirror;
        self.ledger[r as usize].route |= route;
        if self.w.rel(m, r).met {
            return;
        }
        self.w.rel_mut(m, r).met = true;
        self.w.rel_mut(r, m).met = true;
        for (p, q) in [(m, r), (r, m)] {
            let t = self.w.factions[p as usize].traits;
            self.w.rel_mut(p, q).tension += 0.3 * (t.aggressiveness - t.friendliness);
        }
        self.w.stats.contacts += 1;
        self.w.log(ev::CONTACT, m, r, x, y, 0);
        // Told here, not from the log (the log is read before this).
        let _ = self.w.events.pop();
        self.news_seen = self.w.news.next;
        self.tell_contact(r, x, y, route);
    }

    /// Rafts and colonies find the rivals: a boat of the player's within sight of a rival's
    /// village or land, or a settlement of the player's on a rival's landmass.
    fn contacts(&mut self, dt: f32) {
        let m = self.mirror;
        let d = self.w.d;
        let canoe = crate::ages_table::Building::Raft.unlock_age();
        for f in 0..MAX_FACTIONS as u8 {
            if f == m || !self.w.factions[f as usize].alive || self.w.rel(m, f).met {
                continue;
            }
            let mut hit: Option<(i32, i32)> = None;
            for &(bx, by) in &self.player.boats {
                let o = self.w.owner[d.idx(bx as i32, by as i32)];
                let near = o == f || self.w.villages.iter().any(|v| v.alive && v.owner == f && d.dist(v.x as f32, v.y as f32, bx, by) < 26.0);
                if near {
                    hit = Some((bx as i32, by as i32));
                    break;
                }
            }
            if hit.is_none() {
                for &(sx, sy) in &self.player.sites {
                    let l = self.w.terrain.land(sx, sy);
                    let near = self.w.villages.iter().any(|v| v.alive && v.owner == f && l != 0 && self.w.terrain.land(v.x, v.y) == l && d.dist(v.x as f32, v.y as f32, sx as f32, sy as f32) < 90.0);
                    if near {
                        hit = Some((sx, sy));
                        break;
                    }
                }
            }
            // Their canoes find the player's shore: a coastal village of a people with boats,
            // within a long paddle of a settlement of the player's.
            if hit.is_none() && self.w.factions[f as usize].age >= canoe {
                let near = self.w.villages.iter().filter(|v| v.alive && v.owner == f && v.coast).any(|v| self.player.sites.iter().any(|&(sx, sy)| d.dist(v.x as f32, v.y as f32, sx as f32, sy as f32) < 140.0));
                if near && self.rng.chance(0.012 * dt) {
                    hit = self.player.sites.first().copied();
                }
            }
            if let Some((x, y)) = hit {
                self.meet(f, x, y, true);
            }
        }
    }

    /// The nearest (rival village, mirror village) pair the short way round, by sea.
    fn sea_pair(&self, r: u8) -> Option<(u16, usize, f32)> {
        let d = self.w.d;
        let mut best: Option<(u16, usize, f32)> = None;
        for (vi, v) in self.w.villages.iter().enumerate() {
            if !v.alive || v.owner != r {
                continue;
            }
            for (k, mv) in self.vils.iter().enumerate() {
                let dd = d.dist(v.x as f32, v.y as f32, mv.x as f32, mv.y as f32) - if v.coast { 15.0 } else { 0.0 };
                if best.map_or(true, |b| dd < b.2) {
                    best = Some((vi as u16, k, dd.max(1.0)));
                }
            }
        }
        best
    }

    /// Met peoples with no way to the player on foot deal across the sea: tension drifts (the
    /// `politics` rule, weaker with distance), friends trade food by boat, the hostile send
    /// raiding boats, and a war brings a raid every so often until peace.
    fn overseas(&mut self, dt: f32) {
        let m = self.mirror;
        let hostility = self.w.inputs.hostility();
        let larder = self.player.food;
        let d = self.w.d;
        for r in 0..MAX_FACTIONS as u8 {
            if r == m || !self.w.factions[r as usize].alive || !self.w.rel(m, r).met {
                continue;
            }
            let by_land = self.w.near_pairs[r as usize * MAX_FACTIONS + m as usize].2 != NO_V;
            if by_land {
                continue;
            }
            let age = self.w.factions[r as usize].age;
            let led = self.ledger[r as usize];
            // Boats: the player's rafts showed the way, or the rival has its own (Toolmakers).
            if !led.route && age < crate::ages_table::Building::Raft.unlock_age() {
                continue;
            }
            let Some((rv, mk, dist)) = self.sea_pair(r) else { continue };
            let reach = (1.4 - dist / 180.0).clamp(0.25, 1.0);
            let tr = self.w.factions[r as usize].traits;
            let hungry = self.w.factions[r as usize].hungry;
            let mt = self.w.factions[m as usize].traits;
            {
                let rr = self.w.rel_mut(r, m);
                let grudge = 0.5 * rr.grudge.min(1.0);
                // A full larder across the water tempts the bold.
                let covet = if larder >= 5.0 && tr.aggressiveness >= 0.45 { 0.2 } else { 0.0 };
                let p = tr.aggressiveness + hungry * 0.8 + grudge + covet + hostility * 0.6 - tr.friendliness * 0.8 - 0.25;
                rr.tension = (rr.tension + politics::TENSION_RATE * p * dt * reach).clamp(-1.0, 2.0);
            }
            {
                let rm = self.w.rel_mut(m, r);
                let p = mt.aggressiveness + hostility - mt.friendliness * 0.8 - 0.25;
                rm.tension = (rm.tension + politics::TENSION_RATE * p * dt * reach).clamp(-1.0, 2.0);
            }
            let (rel, back) = (*self.w.rel(r, m), *self.w.rel(m, r));
            let target = self.vils.get(mk).copied();
            let Some(target) = target else { continue };
            let rvil = (self.w.villages[rv as usize].x, self.w.villages[rv as usize].y);
            let in_flight = self.boats.iter().any(|b| b.rival == r);
            if in_flight {
                continue;
            }
            let at_war = rel.war == 2 || back.war == 2;
            // Raids: a war sends them every 25–40 s; otherwise tension, temper and the dice.
            if self.ledger[r as usize].raid_cd <= 0.0 {
                let roll = self.rng.f32();
                let rate = self.difficulty.raids;
                let want = at_war || (rel.war == 0 && rel.cooldown <= 0.0 && rel.tension >= RAID_TENSION && tr.aggressiveness >= 0.4 && roll < (0.08 * tr.aggressiveness + 0.08 * self.w.inputs.agitation() + hungry * 0.2) * dt * 4.0 * rate);
                if want {
                    self.ledger[r as usize].raid_cd = if at_war { self.rng.range(25.0, 40.0) } else { self.rng.range(45.0, 70.0) } / rate.max(0.2);
                    let from = (rvil.0 as f32, rvil.1 as f32);
                    let to = (target.x as f32, target.y as f32);
                    let eta = d.dist(from.0, from.1, to.0, to.1) / SAIL;
                    self.boats.push(Boat { rival: r, raid: true, from, to, t: 0.0, eta, target: mk });
                    continue;
                }
            }
            // Trade: friendly both ways, at peace, with food to spare.
            if self.ledger[r as usize].trade_cd <= 0.0 && rel.war == 0 && back.war == 0 && rel.tension <= 0.05 && back.tension <= 0.3 {
                let rich = (0..self.w.villages.len()).filter(|&i| self.w.villages[i].alive && self.w.villages[i].owner == r && self.w.villages[i].food >= 4.0).max_by(|&a, &b| self.w.villages[a].food.total_cmp(&self.w.villages[b].food));
                if let Some(ri) = rich {
                    self.ledger[r as usize].trade_cd = self.rng.range(40.0, 60.0) / reach;
                    self.w.villages[ri].food -= 2.0;
                    let from = (self.w.villages[ri].x as f32, self.w.villages[ri].y as f32);
                    let to = (target.x as f32, target.y as f32);
                    let eta = d.dist(from.0, from.1, to.0, to.1) / SAIL;
                    self.boats.push(Boat { rival: r, raid: false, from, to, t: 0.0, eta, target: mk });
                }
            }
        }
        // Boats sail; on landing a raid steals and a trade run delivers.
        let mut landed: Vec<Boat> = Vec::new();
        for b in self.boats.iter_mut() {
            b.t += dt;
            if b.t >= b.eta {
                landed.push(*b);
            }
        }
        self.boats.retain(|b| b.t < b.eta);
        for b in landed {
            if !self.w.factions[b.rival as usize].alive {
                continue;
            }
            let (x, y) = (b.to.0 as i32, b.to.1 as i32);
            if b.raid {
                self.sea_raid(b.rival, b.target, x, y);
            } else {
                let r = b.rival;
                self.ledger[r as usize].food += 2.0;
                self.w.stats.trades += 1;
                for (p, q, k) in [(r, self.mirror, 0.03), (self.mirror, r, 0.05)] {
                    let rl = self.w.rel_mut(p, q);
                    rl.traded_t = 0.0;
                    rl.tension -= k;
                }
                self.tell_trade(r, x, y);
            }
        }
    }

    /// A raiding boat lands at mirror village `k`: food from the larder (people if it is bare),
    /// and the raiders sail home sated while the player's people remember.
    fn sea_raid(&mut self, r: u8, k: usize, x: i32, y: i32) {
        let m = self.mirror;
        let tr = self.w.factions[r as usize].traits;
        let age = self.w.factions[r as usize].age as f32;
        let larder = if k == 0 { self.player.food } else { 0.0 };
        let dmg = self.difficulty.damage;
        let want = (1.5 + 0.15 * age) * dmg;
        let take = want.min(larder.max(0.0));
        if take >= 0.5 {
            self.ledger[r as usize].food -= take;
        }
        // Nothing to take, or a violent people: someone gets hurt.
        let p_hurt = (if take < 0.5 { 0.35 + 0.5 * tr.violence } else { 0.4 * tr.violence } * dmg).min(1.0);
        if self.rng.chance(p_hurt) {
            self.ledger[r as usize].hurt += 1;
        }
        self.w.stats.raids += 1;
        {
            let rr = self.w.rel_mut(r, m);
            rr.tension = (rr.tension - 0.3).max(-0.2);
            rr.raid_looted = true;
        }
        {
            let rm = self.w.rel_mut(m, r);
            rm.tension = (rm.tension + 0.25).min(2.0);
            rm.grudge += 0.05;
        }
        self.tell_raid(r, x, y);
    }

    /// Space Age: rivals from the Electric Age on race the player to orbit. A rocket takes a
    /// Space Age people about four simulated minutes (less with production and launch pads,
    /// more a few ages back); the first to orbit is told as such.
    fn launch_race(&mut self, dt: f32) {
        if self.player_age() < 19 {
            return;
        }
        for r in 0..MAX_FACTIONS as u8 {
            if r == self.mirror || !self.w.factions[r as usize].alive {
                continue;
            }
            let f = &self.w.factions[r as usize];
            if f.age < 17 {
                continue;
            }
            let pads = self.w.villages.iter().any(|v| v.alive && v.owner == r && v.built & (1u64 << Building::LaunchPad as u8) != 0);
            let rate = (1.0 / LAUNCH_SECONDS) * ((f.age as f32 - 16.0) / 3.0) * (1.0 + 0.25 * f.metrics.production.min(2.0)) * if pads { 1.3 } else { 1.0 };
            let l = &mut self.ledger[r as usize];
            if l.launch >= 1.0 {
                continue;
            }
            l.launch = (l.launch + rate * dt).min(1.0);
            let q = (l.launch * 4.0).floor() as u8;
            if q > l.told_q {
                l.told_q = q;
                let (x, y) = self.capital_xy(r);
                // Every milestone of the leader; the others only when they reach orbit.
                let me = self.ledger[r as usize].launch;
                let leader = (0..MAX_FACTIONS).filter(|&o| o != r as usize && self.w.factions[o].alive).all(|o| self.ledger[o].launch <= me);
                if q >= 4 || leader {
                    self.tell_launch(r, x, y, (q as i32) * 25);
                }
            }
        }
    }

    // -----------------------------------------------------------------------------------
    // Words.

    fn push(&mut self, mut l: HomeLine) {
        self.tally[(l.kind as usize).min(15)] += 1;
        l.seq = self.next_seq;
        self.next_seq += 1;
        if self.lines.len() >= LINES_KEEP {
            self.lines.pop_front();
        }
        self.lines.push_back(l);
    }

    fn name(&self, r: u8) -> String {
        self.w.factions[r as usize].name.clone()
    }

    fn temper(&self, r: u8) -> &'static str {
        let t = self.w.factions[r as usize].traits;
        if t.friendliness > 0.6 && t.aggressiveness < 0.45 {
            "friendly"
        } else if t.aggressiveness > 0.55 {
            "quick to fight"
        } else if t.friendliness < 0.35 {
            "suspicious"
        } else {
            "wary"
        }
    }

    /// Compass direction from the player's camp to (x, y), the short way round.
    fn direction(&self, x: i32, y: i32) -> &'static str {
        let (cx, cy) = self.player.sites.first().copied().unwrap_or((0, 0));
        let d = self.w.d;
        let (dx, dy) = (d.dxi(cx, x) as f32, d.dyi(cy, y) as f32);
        let a = dy.atan2(dx).to_degrees();
        match a {
            a if (-22.5..22.5).contains(&a) => "east",
            a if (22.5..67.5).contains(&a) => "south-east",
            a if (67.5..112.5).contains(&a) => "south",
            a if (112.5..157.5).contains(&a) => "south-west",
            a if (-67.5..-22.5).contains(&a) => "north-east",
            a if (-112.5..-67.5).contains(&a) => "north",
            a if (-157.5..-112.5).contains(&a) => "north-west",
            _ => "west",
        }
    }

    fn site_word(&self, x: i32, y: i32) -> &'static str {
        let d = self.w.d;
        let camp = self.player.sites.first().map_or(true, |&(cx, cy)| d.cheb(cx, cy, x, y) <= 12);
        match (camp, self.phase()) {
            (true, ERA_STONE) => "camp",
            (true, ERA_KINGDOMS) => "capital",
            (true, _) => "city",
            (false, ERA_STONE) => "colony",
            (false, _) => "colony",
        }
    }

    fn tell_contact(&mut self, r: u8, x: i32, y: i32, by_boat: bool) {
        let (n, t) = (self.name(r), self.temper(r));
        let age = ages::name(self.w.factions[r as usize].age);
        let say = match self.phase() {
            ERA_STONE if by_boat => format!("My lord, our rafters found people across the water: the {n}, {t}. They are staring at our chicken."),
            ERA_STONE => format!("We have met the {n}, {t}. They are measuring our spears with their eyes."),
            ERA_INDUSTRY => format!("Our envoys have met the {n} ({age}). They are {t}, and already asking about goats."),
            ERA_SPACE => format!("Contact with the {n} ({age}): {t}. They have a space programme too."),
            _ => format!("We have met the {n}, {t}."),
        };
        self.push(HomeLine {
            kind: he::CONTACT,
            tone: crate::news::TONE_INFO,
            rival: r as i32,
            x,
            y,
            text: format!("First contact: your people meet the {n}"),
            say,
            key: format!("home-contact-{r}"),
            priority: 2,
            cooldown: 4,
            ..Default::default()
        });
    }

    fn tell_arrival(&mut self, r: u8, x: i32, y: i32) {
        let n = self.name(r);
        let dir = self.direction(x, y);
        let t = self.temper(r);
        let first = self.ledger.iter().filter(|l| l.seen).count() == 1;
        let say = if first {
            format!("My lord, we are not alone. A people called the {n} live across the sea to the {dir}. They seem {t}.")
        } else {
            format!("Another people, the {n}, now live to the {dir}. {}", if t == "quick to fight" { "They look like trouble." } else { "They seem to keep to themselves." })
        };
        self.push(HomeLine {
            kind: he::ARRIVE,
            tone: crate::news::TONE_INFO,
            rival: r as i32,
            x,
            y,
            text: format!("A new people, the {n}, settle to the {dir}"),
            say,
            key: if first { "home-arrive-first".into() } else { "home-arrive".into() },
            priority: if first { 2 } else { 1 },
            cooldown: if first { 999 } else { 25 },
            ..Default::default()
        });
    }

    fn tell_raid(&mut self, r: u8, x: i32, y: i32) {
        let now = self.w.time;
        let n = self.name(r);
        let led = &mut self.ledger[r as usize];
        let food = led.food.min(0.0);
        let hurt = led.hurt;
        led.food -= food;
        led.hurt = 0;
        led.told_t = now;
        let place = self.site_word(x, y);
        let lost = (-food).round() as i32;
        let hurt_s = match hurt {
            0 => String::new(),
            1 => " and killed one of ours".to_string(),
            k => format!(" and killed {k} of ours"),
        };
        let (text, say, market) = match self.phase() {
            ERA_STONE | ERA_KINGDOMS => (
                if lost > 0 { format!("RAID: the {n} steal {lost} food from your {place}") } else { format!("RAID: the {n} strike your {place}") },
                format!("Raiders! The {n} hit our {place}{}{hurt_s}. Stress makes them bolder, my lord.", if lost > 0 { format!(", stole {lost} food") } else { String::new() }),
                0.0,
            ),
            ERA_INDUSTRY | ERA_INFO => (format!("{} RAIDERS HIT OUR {}; GOATS SPOOKED", n.to_uppercase(), place.to_uppercase()), format!("The {n} raided our {place}{hurt_s}. The goat market did not enjoy it."), -0.03),
            _ => (format!("{n} saboteurs strike our {place}"), format!("Saboteurs from the {n} hit our {place}{hurt_s}. Calm minds, steady hands, my lord."), -0.02),
        };
        self.push(HomeLine {
            kind: he::RAID,
            tone: crate::news::TONE_BAD,
            rival: r as i32,
            x,
            y,
            food,
            hurt,
            market,
            text,
            say,
            key: "home-raid".into(),
            priority: 3,
            cooldown: 8,
            ..Default::default()
        });
    }

    fn tell_clash(&mut self, r: u8, x: i32, y: i32) {
        let n = self.name(r);
        let now = self.w.time;
        let led = &mut self.ledger[r as usize];
        let hurt = led.hurt;
        led.hurt = 0;
        led.told_t = now;
        if hurt <= 0 {
            return;
        }
        let who = if hurt == 1 { "one of our people".to_string() } else { format!("{hurt} of our people") };
        self.push(HomeLine {
            kind: he::CLASH,
            tone: crate::news::TONE_BAD,
            rival: r as i32,
            x,
            y,
            hurt,
            market: if self.phase() == ERA_INDUSTRY { -0.01 } else { 0.0 },
            text: format!("Skirmish with the {n}: {hurt} of yours fall"),
            say: format!("A skirmish with the {n}. We lost {who}."),
            key: "home-clash".into(),
            priority: 2,
            cooldown: 10,
            ..Default::default()
        });
    }

    fn tell_sack(&mut self, r: u8, x: i32, y: i32) {
        let n = self.name(r);
        let place = self.site_word(x, y);
        let led = &mut self.ledger[r as usize];
        let hurt = led.hurt;
        led.hurt = 0;
        led.told_t = self.w.time;
        let food = -(self.player.food.min(3.0)) * self.difficulty.damage;
        self.push(HomeLine {
            kind: he::SACK,
            tone: crate::news::TONE_BAD,
            rival: r as i32,
            x,
            y,
            food,
            hurt,
            market: if self.phase() >= ERA_INDUSTRY { -0.06 } else { 0.0 },
            text: format!("SACKED: the {n} overrun your {place}"),
            say: format!("The {n} overran our {place}, my lord! Our people hid and came back, but the stores are gone."),
            key: "home-sack".into(),
            priority: 4,
            cooldown: 5,
            ..Default::default()
        });
    }

    fn tell_trade(&mut self, r: u8, x: i32, y: i32) {
        let now = self.w.time;
        let n = self.name(r);
        let led = &mut self.ledger[r as usize];
        let food = led.food.max(0.0);
        led.food -= food;
        led.told_t = now;
        let k = food.round() as i32;
        let (text, say, market) = match self.phase() {
            ERA_STONE | ERA_KINGDOMS => (format!("TRADE: the {n} bring {k} food"), format!("The {n} came with baskets of food. We gave them a pebble. Everyone is delighted."), 0.0),
            ERA_INDUSTRY | ERA_INFO => (format!("{} TRADE DEAL; GOAT INDEX UP", n.to_uppercase()), format!("A trade deal with the {n}. The goat index likes it."), 0.025),
            _ => (format!("The {n} share launch data with us"), format!("The {n} shared rocket data with us. Space is friendlier together."), 0.0),
        };
        self.push(HomeLine {
            kind: he::TRADE,
            tone: crate::news::TONE_GOOD,
            rival: r as i32,
            x,
            y,
            food,
            market,
            text,
            say,
            key: "home-trade".into(),
            priority: 2,
            cooldown: 20,
            ..Default::default()
        });
    }

    fn tell(&mut self, kind: u8, r: u8, x: i32, y: i32) {
        let n = self.name(r);
        let calm_hint = if self.w.inputs.calm > 0.55 { " Your calm reached their chiefs." } else { "" };
        let (tone, text, say, key, priority, market) = match kind {
            he::WAR => (
                crate::news::TONE_BAD,
                format!("WAR: the {n} declare war on your people"),
                format!("The {n} have declared war on us, my lord! {}", if self.w.player_stressed() { "Your stress is not helping." } else { "Calm heads end wars sooner." }),
                "home-war",
                4,
                -0.08,
            ),
            he::PEACE => (crate::news::TONE_GOOD, format!("PEACE with the {n}"), format!("Peace with the {n}.{calm_hint} Someone brought soup."), "home-peace", 3, 0.04),
            he::ALLY => (crate::news::TONE_GOOD, format!("The {n} swear friendship with your people"), format!("The {n} have sworn friendship with us. They want to be invited to the next fire."), "home-ally", 2, 0.02),
            he::LANDING => (
                crate::news::TONE_WARN,
                format!("The {n} land on your shores"),
                format!("My lord, the {n} have settled on our own continent. Neighbours. Lovely. Probably."),
                "home-landing",
                3,
                0.0,
            ),
            _ => return,
        };
        let market = if matches!(self.phase(), ERA_INDUSTRY | ERA_INFO) { market } else { 0.0 };
        self.push(HomeLine { kind, tone, rival: r as i32, x, y, market, text, say, key: key.into(), priority, cooldown: 6, ..Default::default() });
    }

    fn tell_launch(&mut self, r: u8, x: i32, y: i32, pct: i32) {
        let n = self.name(r);
        let mine = (self.player.launch * 100.0).round() as i32;
        let first = pct >= 100 && !self.orbit;
        if pct >= 100 {
            self.orbit = true;
        }
        let (text, say, prio) = if pct >= 100 {
            if self.player.launched || !first {
                let after = if self.player.launched { "after you" } else { "too" };
                (format!("The {n} reach orbit, {after}"), format!("The {n} reached orbit {after}. {}", if self.player.launched { "We waved first." } else { "The sky is getting crowded, my lord." }), 2)
            } else {
                (format!("SPACE RACE: the {n} reach orbit first"), format!("The {n} beat us to orbit, my lord! Their astronauts are waving. Smugly."), 3)
            }
        } else {
            let ahead = pct > mine;
            (
                format!("Space race: the {} rocket is {pct}% built (yours {mine}%)", poss(&n)),
                if ahead { format!("The {n} are {pct}% of the way to orbit, ahead of us. Focus, my lord.") } else { format!("The {n} are building a rocket too ({pct}%). We are ahead, for now.") },
                if ahead { 2 } else { 1 },
            )
        };
        self.push(HomeLine {
            kind: he::LAUNCH,
            tone: if pct >= 100 && !self.player.launched { crate::news::TONE_WARN } else { crate::news::TONE_INFO },
            rival: r as i32,
            x,
            y,
            n: pct,
            text,
            say,
            key: format!("home-launch-{pct}"),
            priority: prio,
            cooldown: 6,
            ..Default::default()
        });
    }

    /// News among the rivals: the sim's own headline, with an advisor line for the big ones,
    /// and in the Industry scene a nudge to the goat market (wars scare it, trade and peace
    /// cheer it).
    fn tell_world(&mut self, e: &Event, l: &crate::news::NewsLine) {
        // The world's big news only: the ticker is shared with the scene's own.
        let worth = match e.kind {
            ev::WAR | ev::PEACE | ev::REBELLION | ev::WIPED | ev::COLLAPSE | ev::CIVIL_WAR | ev::REVOLUTION | ev::VASSAL | ev::PLAGUE | ev::INDEPENDENCE => true,
            ev::AGE_UP => e.n >= 4,
            ev::CONTACT | ev::CAPTURE | ev::BATTLE | ev::TRADE | ev::FAMINE => self.rng.chance(0.35),
            _ => false,
        };
        if l.text.is_empty() || !worth {
            return;
        }
        let market = match e.kind {
            ev::WAR => -0.04,
            ev::PEACE => 0.03,
            ev::TRADE => 0.015,
            ev::CAPTURE | ev::BATTLE => -0.01,
            ev::RAID => -0.005,
            ev::REBELLION | ev::WIPED => -0.02,
            ev::AGE_UP => 0.005,
            _ => 0.0,
        };
        let market = if matches!(self.phase(), ERA_INDUSTRY | ERA_INFO) { market } else { 0.0 };
        let big = matches!(e.kind, ev::WAR | ev::PEACE | ev::REBELLION | ev::WIPED | ev::COLLAPSE);
        let say = if big { l.say.clone() } else { String::new() };
        self.push(HomeLine {
            kind: he::WORLD,
            tone: l.tone,
            rival: e.a,
            x: e.x,
            y: e.y,
            market,
            n: e.kind,
            text: l.text.clone(),
            say,
            key: if big { format!("home-world-{}", e.kind) } else { String::new() },
            priority: 1,
            cooldown: 30,
            ..Default::default()
        });
    }

    // -----------------------------------------------------------------------------------
    // What JS draws.

    /// Refresh the buffers JS reads: rival agents, villages, boats and the rivals' rows.
    pub fn snapshot(&mut self) {
        let m = self.mirror;
        let w = &self.w;
        self.agents_buf.clear();
        for a in w.agents.iter().filter(|a| a.alive && a.faction != m) {
            let kind = if a.state == State::Sail {
                2.0
            } else if a.job.fights() && a.job != Job::Hunt {
                1.0
            } else if a.job.role() == crate::jobs::Role::Settle {
                3.0
            } else {
                0.0
            };
            self.agents_buf.extend_from_slice(&[a.x, a.y, a.faction as f32, a.id as f32, kind]);
        }
        self.villages_buf.clear();
        for v in w.villages.iter().filter(|v| v.alive && v.owner != m) {
            let f = &w.factions[v.owner as usize];
            let capital = w.villages.get(f.capital as usize).map_or(false, |c| c.x == v.x && c.y == v.y);
            let bit = |b: Building| v.built & (1u64 << b as u8) != 0;
            let flags = bit(Building::Field) as u32
                | (bit(Building::Palisade) || v.fx.walls) as u32 * 2
                | (bit(Building::Dock) || bit(Building::Port)) as u32 * 4
                | (v.siege > 0.0) as u32 * 8
                | bit(Building::LaunchPad) as u32 * 16
                | bit(Building::Factory) as u32 * 32
                | (v.raided_t > w.time - 4.0) as u32 * 64;
            self.villages_buf.extend_from_slice(&[v.x as f32, v.y as f32, v.owner as f32, v.pop as f32, v.radius as f32, capital as u8 as f32, flags as f32, f.age as f32, v.built.count_ones() as f32]);
        }
        self.boats_buf.clear();
        for b in &self.boats {
            let (x, y) = b.pos(w.d);
            let facing = if w.d.dx(b.from.0, b.to.0) >= 0.0 { 1.0 } else { -1.0 };
            self.boats_buf.extend_from_slice(&[x, y, b.rival as f32, b.raid as u8 as f32, facing]);
        }
        for f in 0..MAX_FACTIONS {
            let fac = &w.factions[f];
            let o = f * RIVAL_STRIDE;
            let r = w.rel(f as u8, m);
            let back = w.rel(m, f as u8);
            let (cx, cy) = self.capital_xy(f as u8);
            let state = if f as u8 == m {
                3.0
            } else if fac.alive {
                1.0
            } else if fac.pending {
                2.0
            } else {
                0.0
            };
            let vals = [
                state,
                fac.pop as f32,
                fac.villages as f32,
                fac.age as f32,
                fac.color[0] as f32,
                fac.color[1] as f32,
                fac.color[2] as f32,
                self.stance(f as u8) as f32,
                r.tension,
                (r.war.max(back.war)) as f32,
                r.met as u8 as f32,
                cx as f32,
                cy as f32,
                self.ledger[f].launch,
                self.w.owned_tiles[f] as f32,
                if fac.parent == NO_F { -1.0 } else { fac.parent as f32 },
            ];
            self.rivals_buf[o..o + RIVAL_STRIDE].copy_from_slice(&vals);
        }
    }

    /// Rival `r`'s stance toward the player: 0 not met, 1 friendly, 2 neutral, 3 wary,
    /// 4 hostile, 5 raiding, 6 at war, 7 sworn friends.
    pub fn stance(&self, r: u8) -> u8 {
        let m = self.mirror;
        if r == m || (r as usize) >= MAX_FACTIONS {
            return 0;
        }
        let rel = self.w.rel(r, m);
        let back = self.w.rel(m, r);
        if !rel.met {
            0
        } else if rel.war == 2 || back.war == 2 {
            6
        } else if rel.war == 1 || self.boats.iter().any(|b| b.rival == r && b.raid) {
            5
        } else if rel.tension <= -0.35 {
            7
        } else if rel.tension <= 0.0 {
            1
        } else if rel.tension < 0.3 {
            2
        } else if rel.tension < RAID_TENSION {
            3
        } else {
            4
        }
    }

    /// "Ashkai · Bronze Age (8) · wary of you" for a hover label.
    pub fn label(&mut self, r: u8) -> &str {
        self.text.clear();
        if (r as usize) < MAX_FACTIONS {
            let f = &self.w.factions[r as usize];
            let st = ["have not met you", "friendly toward you", "neutral toward you", "wary of you", "hostile to you", "raiding you", "at war with you", "your sworn friends"][self.stance(r) as usize];
            let _ = write!(self.text, "{} · {} ({}) · {}", f.name, ages::name(f.age), f.age, st);
        }
        &self.text
    }

    /// Territory as RGBA, one pixel per `step`×`step` tiles: each rival's colour where it owns
    /// the land, transparent elsewhere (and on the player's own land, which the scene draws).
    pub fn render_territory(&mut self, step: usize) -> (usize, usize) {
        let step = step.max(1);
        let d = self.w.d;
        let (tw, th) = (d.w.div_ceil(step), d.h.div_ceil(step));
        self.territory.clear();
        self.territory.resize(tw * th * 4, 0);
        for ty in 0..th {
            for tx in 0..tw {
                let (x, y) = ((tx * step) as i32, (ty * step) as i32);
                let o = self.w.owner[d.idx(x, y)];
                if o == NO_F || o == self.mirror {
                    continue;
                }
                let c = self.w.factions[o as usize].color;
                // Borders stronger than the inside.
                let edge = [(step as i32, 0), (-(step as i32), 0), (0, step as i32), (0, -(step as i32))].iter().any(|&(ox, oy)| self.w.owner[d.idx(x + ox, y + oy)] != o);
                let i = (ty * tw + tx) * 4;
                self.territory[i..i + 4].copy_from_slice(&[c[0], c[1], c[2], if edge { 220 } else { 110 }]);
            }
        }
        (tw, th)
    }
}

/// "the Halenites' rocket", "the Fenelfolk's rocket".
fn poss(n: &str) -> String {
    if n.ends_with('s') {
        format!("{n}'")
    } else {
        format!("{n}'s")
    }
}

// ---------------------------------------------------------------------------------------
// The war councils, with the player's people kept out of them.

/// Wraps the plugged-in war-and-peace policy (the PPO councils, or None for the rules) so the
/// mirrored faction never raids, declares war or offers alliances on its own: it may only make
/// peace (never as a vassal) and man its walls. The rivals decide exactly as before.
pub struct MirrorGuard {
    pub inner: Option<Box<dyn Policy>>,
    pub mirror: u8,
}

impl Policy for MirrorGuard {
    fn decide(&mut self, w: &World, civ: u8, out: &mut Vec<Decision>) {
        match self.inner.as_mut() {
            Some(p) => p.decide(w, civ, out),
            None => politics::decide_into(w, civ, out),
        }
        if civ == self.mirror {
            out.retain(|d| matches!(d, Decision::KeepPeace | Decision::Fortify | Decision::SueForPeace { .. }));
            for d in out.iter_mut() {
                if let Decision::SueForPeace { with, .. } = *d {
                    *d = Decision::SueForPeace { with, vassal: false };
                }
            }
        }
    }

    fn command(&mut self, w: &mut World) {
        if let Some(p) = self.inner.as_mut() {
            p.command(w);
        }
    }

    fn mobilise(&self, civ: u8) -> Option<f32> {
        if civ == self.mirror {
            return None;
        }
        self.inner.as_ref().and_then(|p| p.mobilise(civ))
    }
}

impl HomeWorld {
    /// Put the guard round whatever policy the world has now (call after `civ_ppo_enable`).
    pub fn guard_policy(&mut self) {
        let inner = self.w.policy.take();
        self.w.policy = Some(Box::new(MirrorGuard { inner, mirror: self.mirror }));
    }
}
